    ('60000000-0000-0000-0000-000000000014','Marie Curie','marie.curie@example.com','07000010014',NULL,'Pioneer of radioactivity and first woman to win a Nobel Prize, she advanced both science and women’s rights.','41000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000002','inactive',v_ts,v_ts,'00000000-0000-0000-0000-111000000002'),
